const body = $input.first().json.body;

// One item per carpark so the search node runs once for each address
return (body.carparks || []).map((c, i) => ({
  json: {
    rank: i + 1,
    car_park_no: c.car_park_no,
    address: c.address,
    destination: body.destination,
    time_context: body.time_context
  }
}));

const inputs = $('Format Input').all().map(i => i.json);
const results = $input.all();

const carparks = inputs.map((cp, i) => {
  const resp = (results[i] && results[i].json) || {};

  const stories = (resp.top_stories || []).map(s =>
    `${s.title || ''} (${s.source || ''}${s.date ? ', ' + s.date : ''})`
  );
  const organic = (resp.organic_results || []).map(r =>
    `${r.title || ''}: ${r.snippet || ''}${r.date ? ' (' + r.date + ')' : ''}`
  );

  // Keep it short: max 3 snippets per carpark, 200 characters each
  const snippets = [...stories, ...organic]
    .map(s => s.slice(0, 200))
    .slice(0, 3);

  return {
    rank: cp.rank,
    car_park_no: cp.car_park_no,
    address: cp.address,
    snippets
  };
});

return [{
  json: {
    time_context: inputs[0] ? inputs[0].time_context : "",
    destination: inputs[0] ? inputs[0].destination : "",
    carparks
  }
}];

parameters.text:
=Singapore HDB parking assistant. Today: {{ $json.time_context }}.
Destination: {{ $json.destination }}

Below are search snippets for each carpark's address. Using ONLY these snippets, assess each carpark for road closures, roadworks, accidents or events today that could raise traffic or fill the carpark. Never invent incidents. If a carpark's snippets show nothing relevant, use "clear".

Reply with ONLY this JSON, one entry per carpark, same order:
{"ai_insights":[{"rank":1,"car_park_no":"","status":"clear|caution|avoid","explanations":["one short sentence"]}]}

clear = nothing found. caution = nearby event or roadworks may raise traffic. avoid = active closure or major event.
If clear, the explanation is "No known incidents or events".

CARPARKS AND SNIPPETS:
{{ JSON.stringify($json.carparks) }}

parameters.jsCode:
const first = $input.first().json;
let text = (first.text || first.output || first.response || "").trim();

// Remove reasoning tags some models add
text = text.replace(/<think>[\s\S]*?<\/think>/g, "").trim();

// Remove markdown code fences
if (text.startsWith("```")) {
  text = text.replace(/^```[^\n]*\n/, "").replace(/```\s*$/, "").trim();
}

// Extract the JSON object
const jsonMatch = text.match(/\{[\s\S]*\}/);
if (jsonMatch) text = jsonMatch[0];

// Use the condensed carpark list to match AI results
const carparks = $("Condense Results").first().json.carparks || [];

try {
  const parsed = JSON.parse(text);

  // Accept either key the model might use
  const list = parsed.ai_insights || parsed.top_3_ai_insights || [];

  const ai_insights = carparks.map((c, i) => {
    const m = list.find(x =>
      x.rank === c.rank ||
      (x.car_park_no && x.car_park_no === c.car_park_no)
    ) || list[i] || {};

    const status = ["clear", "caution", "avoid"].includes(
      String(m.status || "").toLowerCase()
    )
      ? String(m.status).toLowerCase()
      : "unknown";

    return {
      rank: c.rank,
      car_park_no: c.car_park_no,
      status,
      traffic_incident: status === "caution" || status === "avoid",
      explanations:
        Array.isArray(m.explanations) && m.explanations.length
          ? m.explanations
          : ["Live check unavailable"]
    };
  });

  return [{ json: { ai_insights } }];

} catch (err) {
  // If AI output is invalid, don't claim an incident check succeeded
  return [{
    json: {
      ai_insights: carparks.map(c => ({
        rank: c.rank,
        car_park_no: c.car_park_no,
        status: "unknown",
        traffic_incident_flag: false,
        explanations: ["Live check unavailable"]
      }))
    }
  }];
}
